param([string]$EditorPath='D:\Unity\Lib\6000.6.4f1\Editor\Unity.exe')
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent;$stage=Join-Path $repo 'build/phone-test-r24/stage/unity';$output=Join-Path $repo 'build/feedback-1114-r39'
$directory=Get-Content -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/WardrobeDirectory/packs-windows.json') -Raw | ConvertFrom-Json
$packs=@{};foreach($pack in $directory.packs){$packs[$pack.key]=$pack};$wanted=[Collections.Generic.HashSet[string]]::new()
function IncludePack([string]$key){if($wanted.Add($key)){foreach($dep in $packs[$key].dependencies){IncludePack $dep}}}
foreach($item in @('effect_liqi_25hf','ron-flame')){foreach($entry in $directory.items | Where-Object id -eq $item){IncludePack $entry.pack}}
$files=@(& rg --files (Join-Path $repo 'build') -g '*.bundle');$index=@{};foreach($name in $files){$base=[IO.Path]::GetFileName($name);$index[$base]=@($index[$base])+@($name)}
foreach($key in $wanted){$pack=$packs[$key];if($pack.builtin){continue};$source=$null;foreach($file in @($index[$pack.file])+@($index[$pack.sha256+'.bundle'])){if($file -and (Get-Item -LiteralPath $file).Length -eq $pack.bytes -and (Get-FileHash -LiteralPath $file).Hash.ToLowerInvariant() -eq $pack.sha256){$source=$file;break}};if(-not $source){throw "Missing verified test pack: $key"};$folder=Join-Path $output ('wardrobes/'+$key);New-Item -ItemType Directory -Path $folder -Force | Out-Null;$target=Join-Path $folder ($pack.sha256+'.bundle');if(-not (Test-Path -LiteralPath $target)){New-Item -ItemType HardLink -Path $target -Target $source | Out-Null};[IO.File]::WriteAllText($target+'.ok',$pack.sha256)}
foreach($name in @('YakumanCinematic.cs','NativeParticleEffect.cs','NativeEffectMotion.cs','TableEffects.cs','NativeWinPlayback.cs','NativeWinningTileQueue.cs','MatchIntroduction.cs')){Copy-Item -LiteralPath (Join-Path $repo ('unity/Assets/Scripts/'+$name)) -Destination (Join-Path $stage ('Assets/Scripts/'+$name)) -Force}
Copy-Item -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/NativeReview/YakumanR39/catalog.json') -Destination (Join-Path $stage 'Assets/Resources/Majsoul/NativeReview/YakumanR39/catalog.json') -Force
Get-ChildItem -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/NativeReview/YakumanR39') -Filter '*-motion.json' | Copy-Item -Destination (Join-Path $stage 'Assets/Resources/Majsoul/NativeReview/YakumanR39') -Force
Copy-Item -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/Characters/framing.json') -Destination (Join-Path $stage 'Assets/Resources/Majsoul/Characters/framing.json') -Force
Get-ChildItem -LiteralPath (Join-Path $repo 'unity/Assets/Resources/Majsoul/Audio') -File | Where-Object {$_.BaseName -like 'fan_*' -or $_.BaseName -eq 'yiman_preload'} | Copy-Item -Destination (Join-Path $stage 'Assets/Resources/Majsoul/Audio') -Force
Copy-Item -LiteralPath (Join-Path $repo 'tests/YakumanCinematicReview.cs') -Destination (Join-Path $stage 'Assets/Editor/YakumanCinematicReview.cs') -Force
$reviewOutput=if($env:YUNJIAN_YAKUMAN_REVIEW_OUTPUT){$env:YUNJIAN_YAKUMAN_REVIEW_OUTPUT}else{Join-Path $output 'yakuman-review'}
New-Item -ItemType Directory -Path $reviewOutput -Force | Out-Null
foreach($name in @('failed.txt','report.json')){Remove-Item -LiteralPath (Join-Path $reviewOutput $name) -ErrorAction SilentlyContinue}
$prior=$env:YUNJIAN_1114_REPO
try{$env:YUNJIAN_1114_REPO=$repo;$arguments='-batchmode -projectPath "{0}" -executeMethod YunJian.Riichi.Editor.YakumanCinematicReview.Run -logFile "{1}"' -f $stage,($reviewOutput+'.log');$p=Start-Process -FilePath $EditorPath -ArgumentList $arguments -WindowStyle Hidden -PassThru;$p.Id | Set-Content (Join-Path $output 'yakuman-review.pid');$deadline=[DateTime]::UtcNow.AddMinutes(8);while(-not $p.WaitForExit(1000)){if([DateTime]::UtcNow -gt $deadline){Stop-Process -Id $p.Id;throw 'Yakuman review timed out'}};if($p.ExitCode -ne 0){throw 'Yakuman review failed'};Get-Content (Join-Path $reviewOutput 'report.json') -Raw | ConvertFrom-Json | Select-Object checks,@{n='scenes';e={$_.cases.Count}},androidDeviceTested}finally{$env:YUNJIAN_1114_REPO=$prior}
